  external int typeAsInt;

  ob_value_type get type => ob_value_type.fromValue(typeAsInt);
  set type(ob_value_type value) => typeAsInt = value.value;

  @ffi.Int()
  external int b;

  @ffi.Double()
  external double n;

  external ffi.Pointer<ffi.Char> s;

  static ffi.Pointer<ob_value> $allocate(
    ffi.Allocator $allocator, {
    required ob_value_type type,
    required int b,
    required double n,
    required ffi.Pointer<ffi.Char> s,
  }) =>
      $allocator<ob_value>()
        ..ref.type = type
        ..ref.b = b
        ..ref.n = n
        ..ref.s = s;
}

enum ob_value_type {
  OB_VALUE_NONE(0),
  OB_VALUE_BOOL(1),
  OB_VALUE_NUMBER(2),
  OB_VALUE_STRING(3);

  final int value;
  const ob_value_type(this.value);

  static ob_value_type fromValue(int value) => switch (value) {
        0 => OB_VALUE_NONE,
        1 => OB_VALUE_BOOL,
        2 => OB_VALUE_NUMBER,
        3 => OB_VALUE_STRING,
        _ => throw ArgumentError('Unknown value for ob_value_type: $value'),
      };
}
